import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PersonService {

    /** A person's statements: how many were taken, and the last one (null: none). */
    public record Statements(int count, Statement last) {
        public static final Statements NONE = new Statements(0, null);
    }

    private final PersonRepository people;
    private final StatementRepository statements;
    private final SheetService sheets;
    private final RollupService rollups;
    private final Audit audit;

    public PersonService(PersonRepository people, StatementRepository statements, SheetService sheets,
            RollupService rollups, Audit audit) {
        this.people = people;
        this.statements = statements;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's people, in the order they were added. */
    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Each person's statements on the sheet, by person id; a person with none is absent. */
    @Transactional(readOnly = true)
    public Map<Long, Statements> statements(String sheetId) {
        Map<Long, Statements> out = new HashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            out.merge(s.getPersonId(), new Statements(1, s), (was, now) -> new Statements(was.count() + 1, s));
        }
        return out;
    }

    /** Add a person (the sheet is started when it was never loaded before). */
    @Transactional
    public Person add(String sheetId, String user, String name, Grade grade) {
        sheets.load(sheetId, user);
        String trimmed = name.trim();
        requireUnusedName(sheetId, null, trimmed);
        RollupService.Rollup before = rollups.snapshot(sheetId);
        Person saved;
        try {
            saved = people.saveAndFlush(new Person(sheetId, trimmed, grade));
        } catch (DataIntegrityViolationException e) {
            throw nameInUse();
        }
        audit(sheetId, user, "PERSON_ADDED", saved);
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Change a person's name and grade, from the version of them the editor loaded: refused when
     * someone else has saved them since.
     */
    @Transactional
    public Person edit(String sheetId, String user, long personId, long version, String name, Grade grade) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.getVersion() != version) throw editedMeanwhile();
        String trimmed = name.trim();
        requireUnusedName(sheetId, personId, trimmed);
        RollupService.Rollup before = rollups.snapshot(sheetId);
        person.setName(trimmed);
        person.setGrade(grade);
        Person saved;
        try {
            saved = people.saveAndFlush(person);
        } catch (ObjectOptimisticLockingFailureException e) {
            throw editedMeanwhile();
        } catch (DataIntegrityViolationException e) {
            throw nameInUse();
        }
        audit(sheetId, user, "PERSON_EDITED", saved);
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    private void audit(String sheetId, String user, String event, Person person) {
        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " grade=" + person.getGrade());
    }

    /** Refuse a name another person on the sheet already has, ignoring case. */
    private void requireUnusedName(String sheetId, Long personId, String name) {
        String key = name.toLowerCase(Locale.ROOT);
        boolean used = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .anyMatch(p -> !p.getId().equals(personId) && p.getName().toLowerCase(Locale.ROOT).equals(key));
        if (used) throw nameInUse();
    }

    private static ResponseStatusException editedMeanwhile() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Someone else has saved this person since");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use");
    }
}
package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.session.SessionController;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /**
     * A claim; the amount (and a settled claim's fixed due, null otherwise) is sent as text with two
     * decimals so it is never rounded on the way. A claim bound by its person's last statement is
     * stated, with the figure it had then (null: n/a).
     */
    public record ClaimView(long id, long personId, String amount, LocalDate date, String note,
            ClaimStatus status, Integer number, String due, String openedBy, boolean stated, String statedDue) {
        static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getDue() == null ? null : claim.getDue().setScale(2).toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().setScale(2).toPlainString());
        }
    }

    /** The amount is 0.00 or more with up to two decimals; the date defaults to the sheet's today. */
    public record ClaimForm(
            @NotNull @Pattern(regexp = "\\d{1,13}(\\.\\d{1,2})?") String amount,
            LocalDate date,
            @Size(max = 1000) String note) {

        BigDecimal amountValue() {
            return new BigDecimal(amount).setScale(2);
        }
    }

    private final ClaimService service;

    public ClaimController(ClaimService service) {
        this.service = service;
    }

    /** The sheet's claims, newest first. */
    @GetMapping("/claims")
    public List<ClaimView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user) {
        return service.list(sheetId).stream().map(ClaimView::of).toList();
    }

    /** Add a claim for a person. */
    @PostMapping("/people/{personId}/claims")
    public ClaimView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user,
            @Valid @RequestBody ClaimForm form) {
        return ClaimView.of(service.add(sheetId, user, personId, form.amountValue(), form.date(), form.note()));
    }

    /**
     * Take a statement for a person: record their due-total and bind each claim of theirs that counts
     * to its figure now (the others are left unbound). Their claims, newest first.
     */
    @PostMapping("/people/{personId}/statement")
    public List<ClaimView> statement(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user) {
        return service.statement(sheetId, user, personId).stream().map(ClaimView::of).toList();
    }

    /** Change a claim's amount, date and note. */
    @PutMapping("/claims/{claimId}")
    public ClaimView edit(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @PathVariable long claimId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user,
            @Valid @RequestBody ClaimForm form) {
        return ClaimView.of(service.edit(sheetId, user, claimId, form.amountValue(), form.date(), form.note()));
    }

    /**
     * Open, settle or void a claim; a change its status does not allow is refused (409), as is
     * settling it by the user who opened it (403).
     */
    @PostMapping("/claims/{claimId}/{action:open|settle|void}")
    public ClaimView changeStatus(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @PathVariable long claimId,
            @PathVariable String action,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user) {
        ClaimStatus next = switch (action) {
            case "open" -> ClaimStatus.OPEN;
            case "settle" -> ClaimStatus.SETTLED;
            default -> ClaimStatus.VOID;
        };
        return ClaimView.of(service.changeStatus(sheetId, user, claimId, next));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.Statement;
import net.officefloor.hq.app.person.StatementRepository;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateRepository rates;
    private final StatementRepository statements;
    private final SheetService sheets;
    private final RollupService rollups;
    private final PeriodService periods;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates,
            StatementRepository statements, SheetService sheets, RollupService rollups, PeriodService periods,
            Audit audit) {
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.statements = statements;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByIdDesc(sheetId);
    }

    /**
     * Add a claim for a person; without a date it is dated the sheet's today. One dated in a closed
     * period is refused.
     */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
        sheets.lock(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate dated = dateOrToday(sheetId, date);
        periods.requireOpenOn(sheetId, dated);
        RollupService.Rollup before = rollups.snapshot(sheetId);
        Claim saved = claims.saveAndFlush(new Claim(sheetId, personId, amount, dated, noteOf(note)));
        audit(sheetId, user, "CLAIM_ADDED", person, saved, saved.getNumber());
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Change a claim's amount, date and note; without a date it is dated the sheet's today. A claim
     * dated in a closed period, or moved into one, is refused.
     */
    @Transactional
    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note) {
        sheets.lock(sheetId, user);
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        LocalDate dated = dateOrToday(sheetId, date);
        periods.requireOpenOn(sheetId, claim.getDate());
        periods.requireOpenOn(sheetId, dated);
        RollupService.Rollup before = rollups.snapshot(sheetId);
        claim.setAmount(amount);
        claim.setDate(dated);
        claim.setNote(noteOf(note));
        Claim saved = claims.saveAndFlush(claim);
        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        audit(sheetId, user, "CLAIM_EDITED", person, saved, saved.getNumber());
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Move a claim to its next status; a change its current status does not allow is refused, as is
     * settling it by the user who opened it, and any change to a claim dated in a closed period.
     */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
        Sheet sheet = sheets.lock(sheetId, user);
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        periods.requireOpenOn(sheetId, claim.getDate());
        if (!claim.getStatus().canBecome(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next);
        }
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        RollupService.Rollup before = rollups.snapshot(sheetId);
        Integer number = next == ClaimStatus.OPEN ? Integer.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
        claim.setStatus(next);
        claim.setNumber(next == ClaimStatus.VOID ? null : number);
        if (next == ClaimStatus.OPEN) {
            claim.setOpenedBy(user);
        }
        if (next == ClaimStatus.SETTLED) {
            claim.setDue(figure(sheetId, person, claim));
        }
        Claim saved = claims.saveAndFlush(claim);
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            default -> "CLAIM_VOIDED";
        };
        String suffix = next == ClaimStatus.SETTLED
                ? " due=" + (saved.getDue() == null ? "n/a" : saved.getDue().setScale(2).toPlainString())
                : "";
        audit(sheetId, user, event, person, saved, number, suffix);
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Take a statement for a person on the sheet's today: their due-total then (the sum of the figures
     * of their claims that count; n/a when their grade has no rate in force today and none of those
     * claims has a fixed or bound figure) is recorded, and each claim that counts is bound to its
     * figure then, the others left unbound. Their claims, newest first.
     */
    @Transactional
    public List<Claim> statement(String sheetId, String user, long personId) {
        Sheet sheet = sheets.lock(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        RollupService.Rollup before = rollups.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> c.getPersonId().equals(personId))
                .toList();
        List<Claim> counting = theirs.stream().filter(c -> c.getStatus().counts()).toList();
        boolean anyFixed = counting.stream().anyMatch(c -> c.getDue() != null || c.isStated());
        boolean rated = rates.findInForce(sheetId, person.getGrade(), sheet.getToday()).isPresent();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : theirs) {
            if (c.getStatus().counts()) {
                BigDecimal figure = figure(sheetId, person, c);
                if (figure != null) total = total.add(figure);
                c.bind(figure);
            } else {
                c.unbind();
            }
        }
        claims.saveAllAndFlush(theirs);
        BigDecimal dueTotal = rated || anyFixed ? total : null;
        statements.saveAndFlush(new Statement(sheetId, personId, sheet.getToday(), dueTotal, counting.size(), user));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString())
                + " claims=" + counting.size());
        rollups.recordChanges(sheetId, user, before);
        return theirs;
    }

    /** The figure a claim shows (see {@link RollupService#figure}); null when none. */
    private BigDecimal figure(String sheetId, Person person, Claim claim) {
        return rollups.figure(sheetId, person, claim);
    }

    /**
     * Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd; a claim
     * with a number (or, when voided, that had one) ends with it.
     */
    private void audit(String sheetId, String user, String event, Person person, Claim claim, Integer number) {
        audit(sheetId, user, event, person, claim, number, "");
    }

    /** As above, with {@code suffix} (fields a later change added) at the end of the line. */
    private void audit(String sheetId, String user, String event, Person person, Claim claim, Integer number,
            String suffix) {
        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number != null ? " number=" + number : "") + suffix);
    }

    private LocalDate dateOrToday(String sheetId, LocalDate date) {
        return date != null ? date : sheets.today(sheetId);
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.trim();
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Without a transaction the record is appended at once.
     */
    public void recordOnCommit(String entry) {
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

